#include <stdio.h>

int main() {
    long long T, R, B, S, K, W, L;
    char str[8];

    scanf("%lld %lld %lld %lld %lld %lld %lld",
          &T, &R, &B, &S, &K, &W, &L);
    scanf("%7s", str);

    long long values[7];

    values[0] = T;
    values[1] = values[0] * R;
    values[2] = values[1] * B;
    values[3] = values[2] * S;
    values[4] = values[3] * K;
    values[5] = values[4] * W;
    values[6] = values[5] * L;

    for (int i = 0; i < 7; i++) {
        if (str[i] == '1')
            printf("%lld\n", values[i]);
        else
            printf("0\n");
    }

    return 0;
}

